"use client"

import { useState } from "react"
import { Search, SearchX, FileText } from "lucide-react"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogTitle } from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import { Toast, ToastClose, ToastDescription, ToastProvider, ToastTitle, ToastViewport } from "@atlas/ui-web/compositions/Toast/Toast"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Checkbox } from "@atlas/ui-web/primitives/Checkbox/Checkbox"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@atlas/ui-web/primitives/Select/Select"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@atlas/ui-web/primitives/Table/Table"
import { INVOICES_INITIAL, STATUS_TONE, type Invoice, type StatusFilter } from "../schema"

type Props = {
  rows: Invoice[]
  setRows: (rows: Invoice[]) => void
  query: string
  setQuery: (q: string) => void
  status: StatusFilter
  setStatus: (s: StatusFilter) => void
  loading: boolean
}

const SKELETON_ROWS = 6

function matches(r: Invoice, q: string, status: StatusFilter) {
  const needle = q.trim().toLowerCase()
  return (status === "all" || r.status === status) &&
    (!needle || r.id.toLowerCase().includes(needle) || r.customer.toLowerCase().includes(needle))
}

export function InvoicesTable({ rows, setRows, query, setQuery, status, setStatus, loading }: Props) {
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [confirming, setConfirming] = useState(false)
  const [toast, setToast] = useState<string | null>(null)

  const visible = rows.filter((r) => matches(r, query, status))
  // Selection scope is the visible rows: hidden rows are never acted on.
  const chosen = visible.filter((r) => selected.has(r.id))
  const count = chosen.length
  const all: boolean | "indeterminate" = count === 0 ? false : count === visible.length ? true : "indeterminate"

  const toggle = (id: string) =>
    setSelected((s) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); return n })

  // Changing a filter keeps selection only for rows that are still visible.
  const prune = (q: string, s: StatusFilter) =>
    setSelected((prev) => new Set(rows.filter((r) => prev.has(r.id) && matches(r, q, s)).map((r) => r.id)))
  const onQuery = (q: string) => { setQuery(q); prune(q, status) }
  const onStatus = (s: StatusFilter) => { setStatus(s); prune(query, s) }
  const clearFilters = () => { setQuery(""); setStatus("all") }

  const markPaid = () => {
    const ids = new Set(chosen.map((r) => r.id))
    setRows(rows.map((r) => (ids.has(r.id) ? { ...r, status: "Paid" } : r)))
    setSelected(new Set())
    setToast(`${count} invoice${count === 1 ? "" : "s"} marked as paid`)
  }
  const remove = () => {
    const ids = new Set(chosen.map((r) => r.id))
    setRows(rows.filter((r) => !ids.has(r.id)))
    setSelected(new Set())
    setConfirming(false)
  }

  return (
    <ToastProvider>
      <section aria-label="Invoices" style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-3)" }}>
        <h1 style={{
          margin: 0, paddingInline: "var(--atlas-spacing-4)", fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)",
        }}>Invoices</h1>

        <div style={{
          display: "flex", flexWrap: "wrap", gap: "var(--atlas-spacing-2)", paddingInline: "var(--atlas-spacing-4)",
        }}>
          <div style={{ flex: "1 1 var(--atlas-content-width-xs)" }}>
            <Input size="md" type="search" aria-label="Search invoices" placeholder="Search invoice or customer"
              leadingIcon={<Search aria-hidden="true" />} value={query} onChange={(e) => onQuery(e.target.value)} />
          </div>
          <Select value={status} onValueChange={(v) => onStatus(v as StatusFilter)}>
            <SelectTrigger size="md" aria-label="Filter by status">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All statuses</SelectItem>
              <SelectItem value="Paid">Paid</SelectItem>
              <SelectItem value="Pending">Pending</SelectItem>
              <SelectItem value="Overdue">Overdue</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {count > 0 && !loading && (
          <div role="region" aria-label="Bulk actions" style={{
            display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between",
            gap: "var(--atlas-spacing-2)", marginInline: "var(--atlas-spacing-4)",
            padding: "var(--atlas-spacing-2) var(--atlas-spacing-3)", borderRadius: "var(--atlas-radius-md)",
            backgroundColor: "var(--atlas-primary-subtle)", border: "var(--atlas-border-width-1) solid var(--atlas-border)",
          }}>
            <span aria-live="polite" style={{
              fontSize: "var(--atlas-text-body-sm)", fontWeight: "var(--atlas-font-weight-medium)", color: "var(--atlas-foreground)",
            }}>{count} selected</span>
            <div style={{ display: "flex", gap: "var(--atlas-spacing-2)" }}>
              <Button size="sm" variant="primary" onClick={markPaid}>Mark as paid</Button>
              <Button size="sm" variant="destructive" onClick={() => setConfirming(true)}>Delete</Button>
            </div>
          </div>
        )}

        {!loading && visible.length === 0 ? (
          <EmptyInvoices
            noInvoices={rows.length === 0}
            query={query}
            onClear={clearFilters}
            onRestore={() => setRows(INVOICES_INITIAL)}
          />
        ) : (
          <div aria-busy={loading} style={{ overflowX: "auto" }}>
            <div style={{ minInlineSize: "var(--atlas-content-width-lg)" }}>
              <Table aria-label="Invoices">
                <TableHeader>
                  <TableRow>
                    <TableHead>
                      <Checkbox size="sm" aria-label="Select all" checked={all} disabled={loading}
                        onCheckedChange={(c) => setSelected(c === true ? new Set(visible.map((r) => r.id)) : new Set())} />
                    </TableHead>
                    <TableHead>Invoice</TableHead>
                    <TableHead>Customer</TableHead>
                    <TableHead align="end">Amount</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Due date</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {loading
                    ? Array.from({ length: SKELETON_ROWS }, (_, i) => (
                        <TableRow key={i}>
                          <TableCell><Skeleton style={{ inlineSize: "var(--atlas-spacing-4)" }} /></TableCell>
                          <TableCell><Skeleton /></TableCell>
                          <TableCell><Skeleton /></TableCell>
                          <TableCell align="end"><Skeleton /></TableCell>
                          <TableCell><Skeleton /></TableCell>
                          <TableCell><Skeleton /></TableCell>
                        </TableRow>
                      ))
                    : visible.map((r) => (
                        <TableRow key={r.id} selected={selected.has(r.id)}>
                          <TableCell>
                            <Checkbox size="sm" aria-label={`Select ${r.id}, ${r.customer}`}
                              checked={selected.has(r.id)} onCheckedChange={() => toggle(r.id)} />
                          </TableCell>
                          <TableCell>{r.id}</TableCell>
                          <TableCell>{r.customer}</TableCell>
                          <TableCell align="end">{r.amount}</TableCell>
                          <TableCell><Badge variant={STATUS_TONE[r.status]} size="sm">{r.status}</Badge></TableCell>
                          <TableCell>{r.due}</TableCell>
                        </TableRow>
                      ))}
                </TableBody>
              </Table>
            </div>
          </div>
        )}
      </section>

      <AlertDialog open={confirming} onOpenChange={setConfirming}>
        <AlertDialogContent variant="destructive" size="md">
          <AlertDialogTitle>Delete {count} invoice{count === 1 ? "" : "s"}?</AlertDialogTitle>
          <AlertDialogDescription>
            This permanently removes the {count} selected invoice{count === 1 ? "" : "s"} and cannot be undone.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={remove}>Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Toast variant="success" open={toast !== null} onOpenChange={(o) => { if (!o) setToast(null) }}>
        <ToastTitle>{toast}</ToastTitle>
        <ToastDescription>Statuses were updated.</ToastDescription>
        <ToastClose />
      </Toast>
      <ToastViewport />
    </ToastProvider>
  )
}

// Composed locally: Atlas has no EmptyState component (CAND-030).
function EmptyInvoices({ noInvoices, query, onClear, onRestore }: {
  noInvoices: boolean; query: string; onClear: () => void; onRestore: () => void
}) {
  const Icon = noInvoices ? FileText : SearchX
  const trimmed = query.trim()
  return (
    <div role="status" style={{
      display: "grid", justifyItems: "center", textAlign: "center", gap: "var(--atlas-spacing-3)",
      paddingBlock: "var(--atlas-spacing-12)", paddingInline: "var(--atlas-spacing-4)",
