import { InvoicesTable } from "./steps/InvoicesTable"
import { INVOICES_INITIAL, NO_MATCH_QUERY, type Invoice, type StatusFilter } from "./schema"

type Preview = "live" | "loading" | "empty"

export default function InvoicesTablePage() {
  const [rows, setRows] = useState<Invoice[]>(INVOICES_INITIAL)
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState<StatusFilter>("all")
  const [loading, setLoading] = useState(false)

  const q = query.trim().toLowerCase()
  const noMatches = rows.length > 0 && !rows.some(
    (r) => (status === "all" || r.status === status) &&
      (!q || r.id.toLowerCase().includes(q) || r.customer.toLowerCase().includes(q)),
  )
  const preview: Preview = loading ? "loading" : noMatches ? "empty" : "live"

  const setPreview = (next: string) => {
    if (next === "loading") { setLoading(true); return }
    setLoading(false)
    setRows(INVOICES_INITIAL)
    setStatus("all")
    setQuery(next === "empty" ? NO_MATCH_QUERY : "")
  }

  return (
    <FlowShell title="Invoices table" step={0} totalSteps={1} showProgress={false}
      onReset={() => setPreview("live")} phoneBackground="var(--atlas-background)">
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)" }}>
